'use strict';

function makeDependentOptions(groups, selectedGroup) {
  if (!Array.isArray(groups)) throw new TypeError('groups must be an array');
  const seenGroups = [];
  let selected = null;
  for (const item of groups) {
    if (!item || !validCode(item.group) || !Array.isArray(item.choices)) throw new TypeError('invalid group');
    if (seenGroups.some(code => Object.is(code, item.group))) throw new RangeError('duplicate group');
    seenGroups.push(item.group);
    const seenChoices = [];
    const choices = item.choices.map(choice => {
      if (!choice || !validCode(choice.code) || typeof choice.label !== 'string' || choice.label.trim() === '') throw new TypeError('invalid choice');
      if (seenChoices.some(code => Object.is(code, choice.code))) throw new RangeError('duplicate choice');
      seenChoices.push(choice.code);
      return { value: choice.code, label: choice.label.trim() };
    });
    if (Object.is(item.group, selectedGroup)) selected = choices;
  }
  const placeholder = { value: '', label: '[ CHOOSE AN OPTION ]' };
  if (selected === null) return { found: false, options: [placeholder] };
  selected.sort((a, b) => a.label.localeCompare(b.label) || String(a.value).localeCompare(String(b.value)));
  return { found: true, options: [placeholder, ...selected] };
}
function validCode(code) {
  return (typeof code === 'string' && code !== '') || (typeof code === 'number' && Number.isFinite(code) && Boolean(code));
}

module.exports = { makeDependentOptions };

