'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['makeDependentOptions']);
const { makeDependentOptions } = api;
const placeholder = { value: '', label: '[ CHOOSE AN OPTION ]' };

assert.deepStrictEqual(makeDependentOptions([], 0), { found: false, options: [placeholder] });
const groups = [
  {
    group: 0,
    choices: [
      { code: 2, label: 'Zulu' },
      { code: 0, label: 'Alpha' },
      { code: '10', label: 'Alpha' }
    ]
  },
  { group: '0', choices: [{ code: 'x', label: 'Only' }] }
];
const original = JSON.stringify(groups);
assert.deepStrictEqual(makeDependentOptions(groups, 0), {
  found: true,
  options: [
    placeholder,
    { value: 0, label: 'Alpha' },
    { value: '10', label: 'Alpha' },
    { value: 2, label: 'Zulu' }
  ]
});
assert.strictEqual(JSON.stringify(groups), original);
assert.deepStrictEqual(makeDependentOptions(groups, '0'), {
  found: true,
  options: [placeholder, { value: 'x', label: 'Only' }]
});
assert.deepStrictEqual(makeDependentOptions(groups, false), {
  found: false, options: [placeholder]
});

const output = makeDependentOptions(groups, 0);
output.options[1].label = 'changed';
output.options.push({ value: 9, label: 'extra' });
assert.strictEqual(groups[0].choices[1].label, 'Alpha');
assert.strictEqual(makeDependentOptions(groups, 0).options.length, 4);

assert.throws(() => makeDependentOptions(null, 0), TypeError);
assert.throws(() => makeDependentOptions([{ group: {}, choices: [] }], 0), TypeError);
assert.throws(() => makeDependentOptions([{ group: 1, choices: null }], 1), TypeError);
assert.throws(() => makeDependentOptions([{ group: 1, choices: [{ code: NaN, label: 'x' }] }], 1), TypeError);
assert.throws(() => makeDependentOptions([{ group: 1, choices: [{ code: 1, label: '' }] }], 1), TypeError);
assert.throws(() => makeDependentOptions([
  { group: 1, choices: [] }, { group: 1, choices: [] }
], 1), RangeError);
assert.throws(() => makeDependentOptions([{ group: 1, choices: [
  { code: 'a', label: 'A' }, { code: 'a', label: 'B' }
] }], 1), RangeError);

const signedZero = [
  { group: -0, choices: [] },
  { group: 0, choices: [] }
];
assert.strictEqual(makeDependentOptions(signedZero, -0).found, true);
assert.strictEqual(makeDependentOptions(signedZero, 0).found, true);

